(* [comment removed for export] *)
Lemma call_resize (fx : FPState) R M model s sm cr (nn X : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> kept6 R ->
  getr R (reg 10) = Z_to_bv 64 (fb + 376) -> getr R (reg 11) = Z_to_bv 64 nn ->
  0 <= nn <= PM.vs_size (PM.p_tb s) + PM.CHUNK -> nn < 2 ^ 26 + PM.CHUNK ->
  state_ok M model s sm cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (tb' : PM.vstr) (tg' : Z) (cr' : credit),
     regs_preserved R R' -> PM.vs_size tb' = nn -> (nn <= PM.vs_cap (PM.p_tb s) -> PM.vs_own tb' = PM.vs_own (PM.p_tb s) /\ tg' = PM.p_tg s) ->
     (forall l, Z.of_nat (length l) <= Z.min nn (PM.vs_size (PM.p_tb s)) ->                                   (* [comment removed for export] *)
        L5.bytes_at RSEGS M (PM.vs_data (fb + 376) (PM.p_tb s)) l -> L5.bytes_at RSEGS M' (PM.vs_data (fb + 376) tb') l) ->
     state_ok M' model' (PMTK2.with_tb s tb' tg') sm cr' ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x5b2c0 M model) K.
Proof using All.
