(* [comment removed for export] *)
Lemma content_step M M' s sm cr VM scr' (W' : list L5.range) (src' : PM.srcst) (sm' : PM.strm) :
  memrel M -> hi_heap HI (PM.parser_own s ++ LBX) cr M VM -> PM.iss_at RSEGS CAD T3 M (fb + 512) str sm -> 0 <= scr' <= 22528 - 80 ->
  L5C.hpres L (PM.parser_own s ++ LBX) (S - 80) scr' W' M M' ->
  (forall a, PMK.inW W' a -> PMK.inW W0 a \/ exists B m, In (B, m) (PM.parser_own s) /\ B <= a < B + m) ->
  0 <= PEC.pos_of pl src' sm' -> L5.bytes_at RSEGS M' (PM.sr_de src') (UbjRef.slice pl (PEC.pos_of pl src' sm') (PM.sr_rem src')) ->
  (PM.sm_st sm' = 2 -> PM.sm_g sm' = PM.sm_eg sm') ->
